/* dbo.agentCompanySettings + sp_agentCompanySettings / _all / _one — generated by posgmo-factory
   (PRD tests/prd_agentCompanySetting.json, 2026-11-18), fixed by hand: duplicate WHERE in _all,
   FOR JSON AUTO nested the joined agent columns (now PATH), UTC timestamps.
   Needs dbo.agents (sql/sp_agents.sql). Run on DEV, then QA, then PROD.
   The page reuses the 'agents' UI feature: no new uiFeatures row. */
IF OBJECT_ID('dbo.agentCompanySettings','U') IS NULL
BEGIN
CREATE TABLE [dbo].[agentCompanySettings] (
    agentCompanySettingId INT IDENTITY(1,1) NOT NULL,
    companyId INT NOT NULL,
    agentId INT NOT NULL,
    displayName NVARCHAR(80) NULL,
    extraInstructions NVARCHAR(1000) NULL,
    updatedByUserId INT NULL,
    created_At DATETIME NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at DATETIME NULL,
    CONSTRAINT PK_agentCompanySettings PRIMARY KEY CLUSTERED (agentCompanySettingId ASC),
    CONSTRAINT FK_agentCompanySettings_companies FOREIGN KEY (companyId) REFERENCES dbo.companies(companyId),
    CONSTRAINT FK_agentCompanySettings_agents FOREIGN KEY (agentId) REFERENCES dbo.agents(agentId),
    CONSTRAINT UQ_agentCompanySettings_companyId_agentId UNIQUE NONCLUSTERED (companyId, agentId)
);
END
GO


IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_agentCompanySettings_agentId') CREATE NONCLUSTERED INDEX IX_agentCompanySettings_agentId ON dbo.agentCompanySettings (agentId);
GO
CREATE OR ALTER PROC [dbo].[sp_agentCompanySettings]
    @pjsonfile VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Outputmessage NVARCHAR(MAX) = '{
      "result": [
        { "value": "", "msg": "", "error": "" }
      ]
    }';

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @action INT;
        SET @action = (
            SELECT TOP 1 TRY_CONVERT(INT, JSON_VALUE(value, '$.action'))
            FROM OPENJSON(@pjsonfile, '$.agentCompanySettings')
        );

        DECLARE @payload TABLE (
            agentCompanySettingId INT NULL,
            companyId INT NULL,
            agentId INT NULL,
            displayName NVARCHAR(80) NULL,
            extraInstructions NVARCHAR(1000) NULL,
            updatedByUserId INT NULL,
            action INT NULL
        );

        INSERT INTO @payload (agentCompanySettingId, companyId, agentId, displayName, extraInstructions, updatedByUserId, action)
        SELECT
            TRY_CONVERT(INT, JSON_VALUE(value, '$.agentCompanySettingId')),
            TRY_CONVERT(INT, JSON_VALUE(value, '$.companyId')),
            TRY_CONVERT(INT, JSON_VALUE(value, '$.agentId')),
            NULLIF(JSON_VALUE(value, '$.displayName'), ''),
            NULLIF(JSON_VALUE(value, '$.extraInstructions'), ''),
            TRY_CONVERT(INT, JSON_VALUE(value, '$.updatedByUserId')),
            TRY_CONVERT(INT, JSON_VALUE(value, '$.action'))
        FROM OPENJSON(@pjsonfile, '$.agentCompanySettings');

        -- Get core values for validation/upsert from the first entry in payload
        DECLARE @current_companyId INT;
        DECLARE @current_agentId INT;
        DECLARE @current_displayName NVARCHAR(80);
        DECLARE @current_extraInstructions NVARCHAR(1000);
        DECLARE @current_updatedByUserId INT;

        SELECT TOP 1
            @current_companyId = companyId,
            @current_agentId = agentId,
            @current_displayName = displayName,
            @current_extraInstructions = extraInstructions,
            @current_updatedByUserId = updatedByUserId
        FROM @payload
        WHERE action IN (1, 2); -- Applicable for both insert and update

        -- Validate mandatory fields for upsert
        IF @current_companyId IS NULL OR @current_agentId IS NULL
        BEGIN
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'companyId and agentId are required for upsert.');
            COMMIT TRANSACTION;
            GOTO Finish;
        END

        -- Action 1 (INSERT/UPSERT) or Action 2 (UPDATE/UPSERT)
        IF @action IN (1, 2)
        BEGIN
            -- PRD Hint: Refuses an agent with status 'retirado' only on write
            IF EXISTS (SELECT 1 FROM dbo.agents WHERE agentId = @current_agentId AND status = 'retirado')
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Agent is retired and cannot be configured.');
                COMMIT TRANSACTION;
                GOTO Finish;
            END

            -- Check if a record already exists for this companyId and agentId
            IF EXISTS (SELECT 1 FROM dbo.agentCompanySettings WHERE companyId = @current_companyId AND agentId = @current_agentId)
            BEGIN
                -- Perform UPDATE
                UPDATE dbo.agentCompanySettings
                SET
                    displayName = @current_displayName,
                    extraInstructions = @current_extraInstructions,
                    updatedByUserId = @current_updatedByUserId,
                    updated_at = SYSUTCDATETIME()
                WHERE companyId = @current_companyId AND agentId = @current_agentId;
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Updated Successfully');
            END
            ELSE
            BEGIN
                -- Perform INSERT
                INSERT INTO dbo.agentCompanySettings (companyId, agentId, displayName, extraInstructions, updatedByUserId, created_At)
                VALUES (
                    @current_companyId,
                    @current_agentId,
                    @current_displayName,
                    @current_extraInstructions,
                    @current_updatedByUserId,
                    SYSUTCDATETIME()
                );
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Inserted Successfully');
            END
        END
        ELSE IF @action = 3
        BEGIN
            -- PRD Hint: No DELETE action
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Delete action is not supported for agentCompanySettings.');
            COMMIT TRANSACTION;
            GOTO Finish;
        END
        ELSE
        BEGIN
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Invalid action specified.');
            COMMIT TRANSACTION;
            GOTO Finish;
        END

        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', ERROR_MESSAGE());
    END CATCH;

Finish:
    SELECT
        JSON_VALUE(value,'$.value') AS value,
        JSON_VALUE(value,'$.msg') AS msg,
        JSON_VALUE(value,'$.error') AS error
    FROM OPENJSON(@Outputmessage,'$.result');
END;
GO
CREATE OR ALTER PROC [dbo].[sp_agentCompanySettings_all] (@pjsonfile VARCHAR(MAX))
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @companyId INT;
    SET @companyId = TRY_CONVERT(INT,
        (SELECT TOP 1 JSON_VALUE(value, '$.companyId')
         FROM OPENJSON(@pjsonfile, '$.agentCompanySettings'))
    );

    SELECT
        acs.agentCompanySettingId,
        ISNULL(acs.companyId, 0) AS companyId,
        ISNULL(acs.agentId, 0) AS agentId,
        ISNULL(acs.displayName, '') AS displayName,
        ISNULL(acs.extraInstructions, '') AS extraInstructions,
        ISNULL(acs.updatedByUserId, 0) AS updatedByUserId,
        acs.created_At,
        ISNULL(CONVERT(VARCHAR(30), acs.updated_at, 126), '') AS updated_at,
        ISNULL(a.agentKey, '') AS agentKey,
        ISNULL(a.name, '') AS agentName
    FROM dbo.agentCompanySettings AS acs
    LEFT JOIN dbo.agents AS a ON acs.agentId = a.agentId
    WHERE acs.companyId = @companyId
    ORDER BY a.name
    FOR JSON PATH, ROOT('agentCompanySettings');
END;
GO
CREATE OR ALTER PROC [dbo].[sp_agentCompanySettings_one] (@pjsonfile VARCHAR(MAX))
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @agentCompanySettingId INT;
    DECLARE @companyId INT;
    DECLARE @agentId_from_json INT;
    DECLARE @agentKey_from_json NVARCHAR(100);

    SELECT TOP 1
        @agentCompanySettingId = TRY_CONVERT(INT, JSON_VALUE(value, '$.agentCompanySettingId')),
        @companyId = TRY_CONVERT(INT, JSON_VALUE(value, '$.companyId')),
        @agentId_from_json = TRY_CONVERT(INT, JSON_VALUE(value, '$.agentId')),
        @agentKey_from_json = JSON_VALUE(value, '$.agentKey')
    FROM OPENJSON(@pjsonfile, '$.agentCompanySettings');

    -- Resolve agentId from agentKey if agentKey is provided and agentId is not
    IF @agentId_from_json IS NULL AND @agentKey_from_json IS NOT NULL
    BEGIN
        SELECT TOP 1 @agentId_from_json = agentId
        FROM dbo.agents
        WHERE agentKey = @agentKey_from_json;
    END

    SELECT
        acs.agentCompanySettingId,
        ISNULL(acs.companyId, 0) AS companyId,
        ISNULL(acs.agentId, 0) AS agentId,
        ISNULL(acs.displayName, '') AS displayName,
        ISNULL(acs.extraInstructions, '') AS extraInstructions,
        ISNULL(acs.updatedByUserId, 0) AS updatedByUserId,
        acs.created_At,
        ISNULL(CONVERT(VARCHAR(30), acs.updated_at, 126), '') AS updated_at,
        ISNULL(a.agentKey, '') AS agentKey,
        ISNULL(a.name, '') AS agentName
    FROM dbo.agentCompanySettings AS acs
    LEFT JOIN dbo.agents AS a ON acs.agentId = a.agentId
    WHERE (
        (@agentCompanySettingId IS NOT NULL AND acs.agentCompanySettingId = @agentCompanySettingId AND acs.companyId = @companyId)
        OR
        (@agentCompanySettingId IS NULL AND @companyId IS NOT NULL AND @agentId_from_json IS NOT NULL AND acs.companyId = @companyId AND acs.agentId = @agentId_from_json)
    )
    FOR JSON PATH, ROOT('agentCompanySettings');
END;
GO